#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    long long p;
    if (!(cin >> n >> m >> p)) return 0;

    // Precompute factorials and inverse factorials modulo p up to n
    vector<long long> fact(n + 1), invfact(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) fact[i] = fact[i - 1] * i % p;
    auto modpow = [&](long long a, long long e) {
        long long r = 1;
        while (e) {
            if (e & 1) r = r * a % p;
            a = a * a % p;
            e >>= 1;
        }
        return r;
    };
    invfact[n] = modpow(fact[n], p - 2);
    for (int i = n; i > 0; --i) invfact[i - 1] = invfact[i] * i % p;

    auto C = [&](int nn, int kk) -> long long {
        if (kk < 0 || kk > nn) return 0;
        return fact[nn] * invfact[kk] % p * invfact[nn - kk] % p;
    };

    // Precompute powers of 2 up to m
    vector<long long> pow2(m + 1);
    pow2[0] = 1;
    for (int i = 1; i <= m; ++i) pow2[i] = (pow2[i - 1] * 2) % p;

    long long ans = 0;

    // Iterate over all subsets of participants that go left (size k)
    for (int k = 0; k <= m; ++k) {
        int r = m - k;
        long long waysDir = C(m, k); // choose which k go left
        if (waysDir == 0) continue;

        // DP over computers: dp[i][l][r] = number of ways with l left, r right assigned among first i computers
        // and sumMad[i][l][r] = total madness over those ways
        static long long dp[501][501][501];
        static long long sumMad[501][501][501];
        for (int i = 0; i <= n; ++i)
            for (int l = 0; l <= k; ++l)
                for (int rr = 0; rr <= r; ++rr)
                    dp[i][l][rr] = sumMad[i][l][rr] = 0;

        dp[0][0][0] = 1;

        for (int i = 0; i < n; ++i) {
            for (int l = 0; l <= k; ++l) {
                for (int rr = 0; rr <= r; ++rr) {
                    long long cur = dp[i][l][rr];
                    if (!cur) continue;
                    long long curSum = sumMad[i][l][rr];

                    // leave computer i+1 empty
                    dp[i + 1][l][rr] = (dp[i + 1][l][rr] + cur) % p;
                    sumMad[i + 1][l][rr] = (sumMad[i + 1][l][rr] + curSum) % p;

                    // assign a left participant whose target is >= i+1
                    if (l < k) {
                        // number of choices for target position a in [i+1..n]
                        long long choices = (n - (i + 1) + 1);
                        long long addWays = cur * choices % p;
                        dp[i + 1][l + 1][rr] = (dp[i + 1][l + 1][rr] + addWays) % p;
                        // madness contribution: sum over a of (a - (i+1)) = sum_{d=0}^{n-i-1} d
                        long long len = n - i;
                        long long sumd = (len - 1) * len / 2 % p;
                        long long addMad = (cur * sumd) % p;
                        sumMad[i + 1][l + 1][rr] = (sumMad[i + 1][l + 1][rr] + curSum * choices + addMad) % p;
                    }

                    // assign a right participant whose target is <= i+1
                    if (rr < r) {
                        long long choices = (i + 1); // a in [1..i+1]
                        long long addWays = cur * choices % p;
                        dp[i + 1][l][rr + 1] = (dp[i + 1][l][rr + 1] + addWays) % p;
                        // madness: sum_{a=1}^{i+1} ((i+1) - a) = sum_{d=0}^{i} d
                        long long len = i + 1;
                        long long sumd = (len - 1) * len / 2 % p;
                        long long addMad = (cur * sumd) % p;
                        sumMad[i + 1][l][rr + 1] = (sumMad[i + 1][l][rr + 1] + curSum * choices + addMad) % p;
                    }
                }
            }
        }

        long long totalWays = dp[n][k][r];
        long long totalMad = sumMad[n][k][r];

        // For each assignment of targets and directions, we have 2^m ways to choose order of participants
        // but the process depends only on counts and not order, so multiply by 2^m
        long long contrib = totalMad % p;
        contrib = contrib * waysDir % p;
        contrib = contrib * pow2[m] % p;
        ans = (ans + contrib) % p;
    }

    cout << ans % p << '\n';
    return 0;
}

