    if (!(cin >> n >> m >> p)) return 0;

    int N = n, M = m;
    vector<vector<long long>> C(N+1, vector<long long>(N+1,0));
    for(int i=0;i<=N;i++){
        C[i][0]=C[i][i]=1%p;
        for(int j=1;j<i;j++){
            C[i][j]=(C[i-1][j-1]+C[i-1][j])%p;
        }
    }

    vector<long long> pow2(M+1,1%p);
    for(int i=1;i<=M;i++) pow2[i]=pow2[i-1]*2%p;

    vector<long long> fact(N+1,1%p), invfact(N+1,1%p);
    for(int i=1;i<=N;i++) fact[i]=fact[i-1]*i%p;
    auto modpow=[&](long long a,long long e){
        long long r=1%p;
        while(e){
            if(e&1) r=r*a%p;
            a=a*a%p;
            e>>=1;
        }
        return r;
    };
    invfact[N]=modpow(fact[N],p-2);
    for(int i=N;i>0;i--) invfact[i-1]=invfact[i]*i%p;

    auto P=[&](int n,int k)->long long{
        if(k<0||k>n) return 0;
        return fact[n]*invfact[n-k]%p;
    };

    long long ans=0;

    for(int L=0;L<=M;L++){
        int R=M-L;
        for(int k=0;k<=N;k++){
            int s=k;
            int t=N-k;
            if(s<L || t<R) continue;
            long long waysSeats = P(s,L)*P(t,R)%p;
            long long waysAssign = modpow(k,L)*modpow(N-k,R)%p;
            long long waysDir = pow2[M]%p;
            long long totalWays = waysSeats*waysAssign%p*waysDir%p;

            long long sumMad=0;
            if(L>0){
                long long sumPos=0;
                for(int i=1;i<=s;i++){
                    sumPos=(sumPos + i)%p;
                }
                long long sumAssigned=0;
                for(int i=1;i<=k;i++){
                    sumAssigned=(sumAssigned + i)%p;
                }
                long long diff = ( (sumPos - sumAssigned)%p + p )%p;
                sumMad = (sumMad + diff * (long long)L)%p;
            }
            if(R>0){
                long long sumPos=0;
                for(int i=k+1;i<=N;i++){
                    sumPos=(sumPos + i)%p;
                }
                long long sumAssigned=0;
                for(int i=k+1;i<=N;i++){
                    sumAssigned=(sumAssigned + i)%p;
                }
                long long diff = ( (sumAssigned - sumPos)%p + p )%p;
                sumMad = (sumMad + diff * (long long)R)%p;
            }

            ans = (ans + totalWays * sumMad)%p;
        }
    }

    cout << ans%p << '\n';
    return 0;
}

